/* M.V.P. Accelerator, Athleader track: narration text and timing cues (round 3, Dennis). Generated by _generators/cues_r3.py. */
window.NARRATION = {"n_G0": {"dur": 9.6, "text": "Hi, and welcome to the Arena. This first part sets up your season. It takes about fifteen minutes, and you only do it once. Select Start when you're ready.", "sents": [[0, "Hi, and welcome to the Arena.", 0], [2.59, "This first part sets up your season.", 1], [4.79, "It takes about fifteen minutes, and you only do it once.", 1], [7.91, "Select Start when you're ready.", 2]], "v": "r3", "cues": [0, 2.59, 7.91]}, "n_G2": {"dur": 20.48, "text": "Before you meet your Head Coach, here's an idea to keep with you all season. Performance is not determined by what you know. It is determined by what you can summon under pressure. That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book. When you're ready, select Meet your Head Coach.", "sents": [[0, "Before you meet your Head Coach, here's an idea to keep with you all season.", 0], [5.23, "Performance is not determined by what you know.", 1], [7.99, "It is determined by what you can summon under pressure.", 1], [11.33, "That's Dr. Michael Platt, who directs the Wharton Neuroscience Initiative and wrote the foreword to Melissa's book.", 2], [17.63, "When you're ready, select Meet your Head Coach.", 3]], "v": "r3", "cues": [0, 5.23, 11.33, 17.63]}, "n_G4": {"dur": 8.16, "text": "Here's a short message from a leader at your organization, about why it chose this season for its leaders. Watch it through before you move on.", "sents": [[0.03, "Here's a short message from a leader at your organization, about why it chose this season for its leaders.", 0], [6.43, "Watch it through before you move on.", 0]], "v": "r3", "cues": [0.03]}, "n_G5": {"dur": 45.04, "text": "Let's set up your season. First comes your Benchmark Pre-Assessment. It takes about ten minutes, and it opens on the next screen. Next, download your Athleader Playbook. Your practice, your preparation and your reflection for every lesson live in it, so save it somewhere you'll find it again. Then get the agenda for your Starting Line meeting. That's a thirty-minute conversation with your Player-Coach, your manager, about what you're working toward, and they'll set it up. Last, block about an hour a week: your lesson, then one core rep from your Playbook. Pick Google Calendar or Outlook and it goes straight into your calendar, or use the other option for Apple and anything else. Move it when you need to, as long as you keep it. Select Next when you're ready to start your pre-assessment.", "sents": [[0, "Let's set up your season.", 0], [1.83, "First comes your Benchmark Pre-Assessment.", 1], [4.45, "It takes about ten minutes, and it opens on the next screen.", 1], [7.87, "Next, download your Athleader Playbook.", 2], [10.75, "Your practice, your preparation and your reflection for every lesson live in it, so save it somewhere you'll find it again.", 2], [17.55, "Then get the agenda for your Starting Line meeting.", 3], [20.53, "That's a thirty-minute conversation with your Player-Coach, your manager, about what you're working toward, and they'll set it up.", 3], [27.19, "Last, block about an hour a week: your lesson, then one core rep from your Playbook.", 4], [32.85, "Pick Google Calendar or Outlook and it goes straight into your calendar, or use the other option for Apple and anything else.", 4], [39.45, "Move it when you need to, as long as you keep it.", 4], [42.27, "Select Next when you're ready to start your pre-assessment.", 5]], "v": "r3", "cues": [0, 1.83, 7.87, 17.55, 27.19, 42.27]}, "n_G7": {"dur": 39.68, "text": "People often ask about their Player-Coach at this point, so here are the answers. If your manager isn't taking part, that's okay. Your Player-Coach doesn't have to be your direct manager. You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust. Whenever you see Player-Coach, think of that person. Only managers your company selects will have access to the manager track. If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start. After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", "sents": [[0.03, "People often ask about their Player-Coach at this point, so here are the answers.", 0], [4.85, "If your manager isn't taking part, that's okay.", 1], [8.01, "Your Player-Coach doesn't have to be your direct manager.", 1], [11.13, "You might report to more than one manager, or have none taking part at all, so choose a peer, a mentor or a colleague you trust.", 1], [19.03, "Whenever you see Player-Coach, think of that person.", 1], [22.37, "Only managers your company selects will have access to the manager track.", 1], [26.01, "If you manage several people who are taking part, hold one thirty-minute Commitment Meeting with each of them at the start.", 2], [33.41, "After that, build the fifteen-minute check-ins into meetings you already have, so there's nothing extra to schedule.", 2]], "v": "r3", "cues": [0.03, 4.85, 26.01]}, "n_G8": {"dur": 26.08, "text": "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset. You don't need to read it to take part. Each lesson names the chapter if you'd like to go further, and the Foundation Reset you'll learn in Lesson 1 comes straight from it. Your 90-Day Way Scorecard is where the season turns into results. You'll fill it in lesson by lesson and track your goals in it week by week. Download it now, and open the example to see what a finished one looks like.", "sents": [[0, "This course is built from Melissa's book, Athleadership: The Elite Athletic Mindset.", 0], [5.31, "You don't need to read it to take part.", 1], [7.33, "Each lesson names the chapter if you'd like to go further, and the Foundation Reset you'll learn in Lesson 1 comes straight from it.", 1], [14.27, "Your 90-Day Way Scorecard is where the season turns into results.", 2], [18.43, "You'll fill it in lesson by lesson and track your goals in it week by week.", 2], [22.49, "Download it now, and open the example to see what a finished one looks like.", 3]], "v": "r3", "cues": [0, 5.31, 14.27, 22.49]}, "n_G9": {"dur": 47.76, "text": "Every lesson follows the same steps, so you'll always know where you are. From Lesson 2, each lesson opens with a moment of pressure you'll probably recognize. Then a quick check-in, where you notice what went on in you. Only you see what you write. Next come the core lessons, a few short videos each time. You make a call on a real situation, then run a short drill that puts you under a little pressure and asks you to respond. The practice happens in your Playbook during the week, starting with one core rep. Practice on your own and with others, and ask for feedback on how it's landing. Each lesson also brings in an Athleader Pro, with a three-minute drill of their own. A quick Pulse Check after every lesson tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", "sents": [[0, "Every lesson follows the same steps, so you'll always know where you are.", 0], [4.59, "From Lesson 2, each lesson opens with a moment of pressure you'll probably recognize.", 1], [9.83, "Then a quick check-in, where you notice what went on in you.", 1], [13.27, "Only you see what you write.", 1], [15.33, "Next come the core lessons, a few short videos each time.", 2], [19.05, "You make a call on a real situation, then run a short drill that puts you under a little pressure and asks you to respond.", 2], [25.99, "The practice happens in your Playbook during the week, starting with one core rep.", 3], [30.83, "Practice on your own and with others, and ask for feedback on how it's landing.", 3], [35.01, "Each lesson also brings in an Athleader Pro, with a three-minute drill of their own.", 3], [39.65, "A quick Pulse Check after every lesson tracks how you're changing across the season, and a short knowledge check covers the main ideas before you close the lesson.", 4]], "v": "r3", "cues": [0, 4.59, 15.33, 25.99, 39.65]}, "n_G10": {"dur": 12.48, "text": "Your starting point is recorded and Lesson 1 is open. Nice work getting set up. Lesson 1 starts with where you are, and gives you one tool you'll use all season. Select Open Lesson 1 when you're ready.", "sents": [[0.01, "Your starting point is recorded and Lesson 1 is open.", 0], [3.57, "Nice work getting set up.", 0], [5.43, "Lesson 1 starts with where you are, and gives you one tool you'll use all season.", 1], [10.37, "Select Open Lesson 1 when you're ready.", 1]], "v": "r3", "cues": [0.01, 5.43]}, "n_1_0": {"dur": 9.12, "text": "Lesson 1 is about where you start. You'll spend about thirty-five minutes here, then one core rep in your Playbook during the week. Select Start lesson.", "sents": [[0, "Lesson 1 is about where you start.", 0], [2.67, "You'll spend about thirty-five minutes here, then one core rep in your Playbook during the week.", 1], [7.65, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 2.67]}, "n_1_4": {"dur": 35.52, "text": "Here's what you'll practice in this lesson. When something you were counting on falls through, you'll catch your first reaction before you act on it. You'll notice what went through your head, and what you wanted to do. You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing. Melissa calls them the Core 4. You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run. And you'll write your why, in one sentence, in your Playbook this week. The Pulse Check at the end of the lesson picks this up.", "sents": [[0.01, "Here's what you'll practice in this lesson.", 0], [2.37, "When something you were counting on falls through, you'll catch your first reaction before you act on it.", 1], [8.33, "You'll notice what went through your head, and what you wanted to do.", 1], [12.09, "You'll learn what this season conditions: Agility, Resilience, Alignment and Wellbeing.", 2], [18.37, "Melissa calls them the Core 4.", 2], [20.71, "You'll see how your operating system fits together, with the M.V.P. Blueprint as the engine and the 90-Day Way as the loop you run.", 3], [28.69, "And you'll write your why, in one sentence, in your Playbook this week.", 4], [33.05, "The Pulse Check at the end of the lesson picks this up.", 4]], "v": "r3", "cues": [0.01, 2.37, 12.09, 20.71, 28.69]}, "n_1_7": {"dur": 12.0, "text": "Melissa mentioned your Athleader Playbook. Download it now, because every lesson uses it. It opens in a new tab. Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", "sents": [[0.05, "Melissa mentioned your Athleader Playbook.", 0], [2.47, "Download it now, because every lesson uses it.", 0], [5.73, "It opens in a new tab.", 1], [7.21, "Save a copy somewhere you'll find it, and if you already saved it during setup, you're all set.", 1]], "v": "r3", "cues": [0.05, 5.73]}, "n_1_R": {"dur": 49.92, "text": "Before your first Moment, here's one tool you'll use all season. It's called the Foundation Reset, and it comes from Melissa's book. Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex. Your five words tell the alarm to stand down, and bring your thinking brain back online. Melissa used it in a hotel hallway, two days before her biggest summit, as the world shut down. Five words: I'm not in danger, deciding. Two options: cancel or pivot? One default: we pivot, now. Thirty-eight hours later, one of the first global virtual leadership events went live. Now write your own five words. Use one of Melissa's to start, or write words that would steady you. Select Save, and you'll see them again in every check-in.", "sents": [[0.03, "Before your first Moment, here's one tool you'll use all season.", 0], [4.39, "It's called the Foundation Reset, and it comes from Melissa's book.", 0], [8.29, "Under pressure, your brain's alarm, the amygdala, fires faster than the part that plans, the prefrontal cortex.", 1], [15.43, "Your five words tell the alarm to stand down, and bring your thinking brain back online.", 1], [20.53, "Melissa used it in a hotel hallway, two days before her biggest summit, as the world shut down.", 2], [26.49, "Five words: I'm not in danger, deciding.", 2], [30.13, "Two options: cancel or pivot?", 2], [32.95, "One default: we pivot, now.", 2], [34.15, "Thirty-eight hours later, one of the first global virtual leadership events went live.", 2], [41.29, "Now write your own five words.", 3], [43.11, "Use one of Melissa's to start, or write words that would steady you.", 3], [46.79, "Select Save, and you'll see them again in every check-in.", 3]], "v": "r3", "cues": [0.03, 8.29, 20.53, 41.29]}, "n_1_1": {"dur": 11.2, "text": "Read this moment, and picture yourself in it. In moments like this, you don't rise to what you know. You rely on what you've practiced, and that's what this season works on.", "sents": [[0.07, "Read this moment, and picture yourself in it.", 0], [3.59, "In moments like this, you don't rise to what you know.", 1], [7.05, "You rely on what you've practiced, and that's what this season works on.", 1]], "v": "r3", "cues": [0.07, 3.59]}, "n_1_3": {"dur": 12.88, "text": "Before any coaching, take one clean read of how you react. This drill is short. Press play. Melissa will stop partway through and ask what you notice. Type your answer, and the video carries on.", "sents": [[0.03, "Before any coaching, take one clean read of how you react.", 0], [4.65, "This drill is short.", 0], [5.97, "Press play.", 1], [7.05, "Melissa will stop partway through and ask what you notice.", 1], [10.57, "Type your answer, and the video carries on.", 1]], "v": "r3", "cues": [0.03, 5.97]}, "n_1_8": {"dur": 11.44, "text": "Agility, Resilience, Alignment and Wellbeing are what this season conditions. Select each one to hear what changes when it's conditioned. Open all four before you move on.", "sents": [[0, "Agility, Resilience, Alignment and Wellbeing are what this season conditions.", 0], [5.89, "Select each one to hear what changes when it's conditioned.", 1], [9.35, "Open all four before you move on.", 1]], "v": "r3", "cues": [0, 5.89]}, "n_1_8_agility": {"dur": 12.24, "text": "When agility is conditioned, you don't need certainty to move. You make the call and adjust as things change. When it isn't, you wait for certainty while everything keeps changing around you.", "sents": [[0.01, "When agility is conditioned, you don't need certainty to move.", 0], [4.43, "You make the call and adjust as things change.", 0], [7.55, "When it isn't, you wait for certainty while everything keeps changing around you.", 1]], "v": "r3", "cues": [0.01, 7.55]}, "n_1_8_resilience": {"dur": 10.24, "text": "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play. When it isn't, one hard moment follows you into the next one.", "sents": [[0.07, "When resilience is conditioned, a setback becomes a lesson you can use, and you're ready for the next play.", 0], [6.47, "When it isn't, one hard moment follows you into the next one.", 1]], "v": "r3", "cues": [0.07, 6.47]}, "n_1_8_alignment": {"dur": 11.84, "text": "When alignment is conditioned, you know what matters most. You make the hard call and keep people moving in the same direction. When it isn't, everything feels urgent and people pull different ways.", "sents": [[0.07, "When alignment is conditioned, you know what matters most.", 0], [3.87, "You make the hard call and keep people moving in the same direction.", 0], [7.65, "When it isn't, everything feels urgent and people pull different ways.", 1]], "v": "r3", "cues": [0.07, 7.65]}, "n_1_8_wellbeing": {"dur": 12.08, "text": "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises. When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", "sents": [[0.01, "When wellbeing is conditioned, you manage your energy and your boundaries, so your best is still there when demand rises.", 0], [7.77, "When it isn't, you're leading on fumes by Wednesday, and everyone can tell.", 1]], "v": "r3", "cues": [0.01, 7.77]}, "n_1_9": {"dur": 38.0, "text": "Your M.V.P. Blueprint is the engine. It's your mission, your vision and your purpose, written down. Most leaders have a purpose, but fewer than one in five can say theirs in a sentence. The 90-Day Way is the loop you run that engine in. Your 90-day plan starts from your mission, vision and purpose, and turns them into two or three clear goals, for your work and for your life outside it. You plan, carry out the plan, reflect every week, then reset and start the next season. The Blueprint tells you where you're going and why it matters. The 90-Day Way is how you get a little closer to it every week.", "sents": [[0.01, "Your M.V.P. Blueprint is the engine.", 0], [2.75, "It's your mission, your vision and your purpose, written down.", 0], [7.05, "Most leaders have a purpose, but fewer than one in five can say theirs in a sentence.", 1], [12.27, "The 90-Day Way is the loop you run that engine in.", 2], [15.55, "Your 90-day plan starts from your mission, vision and purpose, and turns them into two or three clear goals, for your work and for your life outside it.", 2], [24.89, "You plan, carry out the plan, reflect every week, then reset and start the next season.", 2], [30.75, "The Blueprint tells you where you're going and why it matters.", 3], [34.19, "The 90-Day Way is how you get a little closer to it every week.", 3]], "v": "r3", "cues": [0.01, 7.05, 12.27, 30.75]}, "n_1_10": {"dur": 8.4, "text": "Back to Thursday at 4:40, with the plan due at six. Pick the move you'd make, and you'll hear where it leads. You can try the other one afterwards.", "sents": [[0.03, "Back to Thursday at 4:40, with the plan due at six.", 0], [3.93, "Pick the move you'd make, and you'll hear where it leads.", 1], [6.77, "You can try the other one afterwards.", 1]], "v": "r3", "cues": [0.03, 3.93]}, "n_1_10_o0": {"dur": 12.0, "text": "Answering emails until six feels productive, and under pressure it's a normal reaction. It isn't a system, though, so tomorrow looks exactly like today. Try the other option to compare.", "sents": [[0.03, "Answering emails until six feels productive, and under pressure it's a normal reaction.", 0], [5.87, "It isn't a system, though, so tomorrow looks exactly like today.", 0], [10.27, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "n_1_10_o1": {"dur": 14.32, "text": "Three minutes to name the one outcome that matters, then work back from it. That's the rep. By six, your manager needs your direction, not every detail, so share where you're heading and use their feedback to align before you fill in the rest.", "sents": [[0.01, "Three minutes to name the one outcome that matters, then work back from it.", 0], [4.45, "That's the rep.", 0], [5.63, "By six, your manager needs your direction, not every detail, so share where you're heading and use their feedback to align before you fill in the rest.", 0]], "v": "r3", "cues": [0.01]}, "n_1_12": {"dur": 29.44, "text": "Your core rep this week is your why, and it takes about ten minutes. Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence. If you have more time, rate yourself from one to five on each of the Core 4. It's your starting point, and you'll come back to it in Lesson 6. And confirm your weekly hour and sign your commitment. Run your core rep, then ask one person how it landed. Select Open your Lesson 1 pages to get started.", "sents": [[0.01, "Your core rep this week is your why, and it takes about ten minutes.", 0], [4.35, "Picture the end of the season, name the one change you most want to have made, and write your intention in one sentence.", 0], [11.51, "If you have more time, rate yourself from one to five on each of the Core 4.", 1], [16.03, "It's your starting point, and you'll come back to it in Lesson 6.", 1], [19.65, "And confirm your weekly hour and sign your commitment.", 2], [22.83, "Run your core rep, then ask one person how it landed.", 3], [25.69, "Select Open your Lesson 1 pages to get started.", 3]], "v": "r3", "cues": [0.01, 11.51, 19.65, 22.83]}, "n_1_13": {"dur": 10.24, "text": "Each lesson brings in an Athleader Pro, a leader who lives one part of this work. This time it's Tracey Newell, the Change Commander. Press play to hear from her.", "sents": [[0, "Each lesson brings in an Athleader Pro, a leader who lives one part of this work.", 0], [5.51, "This time it's Tracey Newell, the Change Commander.", 1], [8.81, "Press play to hear from her.", 1]], "v": "r3", "cues": [0, 5.51]}, "n_1_14": {"dur": 11.52, "text": "Now try Tracey's drill. It takes three minutes. Select Start the timer and work through each step as it lights up. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "Now try Tracey's drill.", 0], [1.79, "It takes three minutes.", 0], [3.35, "Select Start the timer and work through each step as it lights up.", 1], [7.27, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 3.35]}, "n_1_16_q0": {"dur": 8.48, "text": "A few questions to check the main ideas. First: which of these best describes conditioning? Choose one, then select Submit.", "sents": [[0, "A few questions to check the main ideas.", 0], [2.51, "First: which of these best describes conditioning?", 0], [6.29, "Choose one, then select Submit.", 0]], "v": "r3", "cues": [0]}, "n_1_16_w0": {"dur": 9.04, "text": "Conditioning is what you can consistently access under pressure, when there's no time to think. Knowledge is what you can recall when there is time.", "sents": [[0.03, "Conditioning is what you can consistently access under pressure, when there's no time to think.", 0], [5.89, "Knowledge is what you can recall when there is time.", 0]], "v": "r3", "cues": [0.03]}, "n_1_16_q1": {"dur": 3.36, "text": "In your operating system, what is the 90-Day Way?", "sents": [[0, "In your operating system, what is the 90-Day Way?", 0]], "v": "r3", "cues": [0]}, "n_1_16_w1": {"dur": 12.8, "text": "The 90-Day Way is the execution loop: plan, execute, reflect and reset, every ninety days, so your priorities turn into practice. Your M.V.P. Blueprint is the engine it runs.", "sents": [[0.03, "The 90-Day Way is the execution loop: plan, execute, reflect and reset, every ninety days, so your priorities turn into practice.", 0], [9.49, "Your M.V.P. Blueprint is the engine it runs.", 0]], "v": "r3", "cues": [0.03]}, "n_1_16_q2": {"dur": 6.4, "text": "A key supplier cancels an hour before your big meeting. Which response shows conditioned agility?", "sents": [[0, "A key supplier cancels an hour before your big meeting.", 0], [3.97, "Which response shows conditioned agility?", 0]], "v": "r3", "cues": [0]}, "n_1_16_w2": {"dur": 8.0, "text": "When agility is conditioned, you don't need certainty to move. You decide on what you have and keep adjusting as things change.", "sents": [[0.03, "When agility is conditioned, you don't need certainty to move.", 0], [4.31, "You decide on what you have and keep adjusting as things change.", 0]], "v": "r3", "cues": [0.03]}, "n_1_16_q3": {"dur": 5.12, "text": "Last one. Why does the course ask for your first reaction before any coaching?", "sents": [[0.07, "Last one.", 0], [1.25, "Why does the course ask for your first reaction before any coaching?", 0]], "v": "r3", "cues": [0.07]}, "n_1_16_w3": {"dur": 6.56, "text": "Your first read is a baseline. Every later lesson measures against it, and it stays private to you.", "sents": [[0.01, "Your first read is a baseline.", 0], [2.39, "Every later lesson measures against it, and it stays private to you.", 0]], "v": "r3", "cues": [0.01]}, "n_1_17": {"dur": 34.32, "text": "Before you go, here's what to keep from this lesson. Conditioning is what you can consistently access under pressure, so this season is built on practice rather than more knowledge. The Core 4 are what you condition. Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle you run them in. Your why is the first rep. It's your core rep in the Playbook this week. Select Download my answers for a Word copy of everything you wrote in this lesson. If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", "sents": [[0.03, "Before you go, here's what to keep from this lesson.", 0], [3.43, "Conditioning is what you can consistently access under pressure, so this season is built on practice rather than more knowledge.", 1], [11.37, "The Core 4 are what you condition.", 2], [13.81, "Your M.V.P. Blueprint drives them, and the 90-Day Way is the cycle you run them in.", 2], [19.05, "Your why is the first rep.", 3], [21.23, "It's your core rep in the Playbook this week.", 3], [23.91, "Select Download my answers for a Word copy of everything you wrote in this lesson.", 4], [28.07, "If you'd like to go further, Chapter 4 of the book explains why conditioning is different from training.", 4]], "v": "r3", "cues": [0.03, 3.43, 11.37, 19.05, 23.91]}, "n_1_18": {"dur": 13.04, "text": "That's Lesson 1 done. Way to go, you've entered the Arena. This week, run your core rep, your why, and ask one person how it landed. Next time, in Lesson 2, you'll start on your Inner Blueprint.", "sents": [[0, "That's Lesson 1 done.", 0], [1.73, "Way to go, you've entered the Arena.", 0], [4.51, "This week, run your core rep, your why, and ask one person how it landed.", 1], [9.43, "Next time, in Lesson 2, you'll start on your Inner Blueprint.", 1]], "v": "r3", "cues": [0, 4.51]}, "n_2_0": {"dur": 15.36, "text": "Lesson 2 is your pre-season. You'll collect the raw material for your leadership blueprint: your values, your strengths, your energy and your own game tape. Plan on about forty minutes here, then one core rep this week. Select Start lesson.", "sents": [[0, "Lesson 2 is your pre-season.", 0], [2.49, "You'll collect the raw material for your leadership blueprint: your values, your strengths, your energy and your own game tape.", 1], [9.95, "Plan on about forty minutes here, then one core rep this week.", 1], [13.91, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 2.49]}, "n_2_1": {"dur": 15.28, "text": "Read this moment, and notice what it stirs up in you. When a change like this hits hard, there's usually a value underneath it that you've never named. This lesson helps you name it, along with your strengths, your energy and your own game tape.", "sents": [[0, "Read this moment, and notice what it stirs up in you.", 0], [3.99, "When a change like this hits hard, there's usually a value underneath it that you've never named.", 1], [9.87, "This lesson helps you name it, along with your strengths, your energy and your own game tape.", 1]], "v": "r3", "cues": [0, 3.99]}, "n_2_3": {"dur": 7.28, "text": "A quick look back at Lesson 1 before you start. Choose the sentence that describes conditioning. This one isn't scored.", "sents": [[0, "A quick look back at Lesson 1 before you start.", 0], [2.99, "Choose the sentence that describes conditioning.", 1], [5.73, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.99]}, "n_2_4": {"dur": 31.76, "text": "This lesson is about choosing your next move on purpose when the plan changes, checked against values you've named, so your first reaction doesn't choose for you. You'll narrow a long list down to the three to five values you'd hold even when it costs you. You'll learn to tell a strength from a skill. Both matter, and a strength also tends to give you energy. You'll map what fuels you and what drains you in a real week. Then you'll read your own game tape: one high point and one setback, looked at the way a coach reviews film.", "sents": [[0.01, "This lesson is about choosing your next move on purpose when the plan changes, checked against values you've named, so your first reaction doesn't choose for you.", 0], [9.91, "You'll narrow a long list down to the three to five values you'd hold even when it costs you.", 1], [15.29, "You'll learn to tell a strength from a skill.", 2], [17.89, "Both matter, and a strength also tends to give you energy.", 2], [21.59, "You'll map what fuels you and what drains you in a real week.", 3], [24.85, "Then you'll read your own game tape: one high point and one setback, looked at the way a coach reviews film.", 4]], "v": "r3", "cues": [0.01, 9.91, 15.29, 21.59, 24.85]}, "n_2_7": {"dur": 7.52, "text": "Here are the four parts of your Inner Blueprint. You'll collect them in your Playbook this week. Select each one to hear what to look for.", "sents": [[0.03, "Here are the four parts of your Inner Blueprint.", 0], [2.95, "You'll collect them in your Playbook this week.", 0], [5.17, "Select each one to hear what to look for.", 1]], "v": "r3", "cues": [0.03, 5.17]}, "n_2_7_values": {"dur": 10.88, "text": "Values are what you'd hold on to even when it costs you something. Aim for three to five. With twenty values you have no way to choose between them, and choosing is the whole point.", "sents": [[0, "Values are what you'd hold on to even when it costs you something.", 0], [4.11, "Aim for three to five.", 0], [5.87, "With twenty values you have no way to choose between them, and choosing is the whole point.", 0]], "v": "r3", "cues": [0]}, "n_2_7_strengths": {"dur": 11.52, "text": "A strength is something you do well that also tends to give you energy. A skill is something you've learned to do well. Both matter, and knowing which is which helps you choose where to lean in.", "sents": [[0, "A strength is something you do well that also tends to give you energy.", 0], [4.63, "A skill is something you've learned to do well.", 0], [7.49, "Both matter, and knowing which is which helps you choose where to lean in.", 0]], "v": "r3", "cues": [0]}, "n_2_7_energy": {"dur": 9.44, "text": "Your energy map shows which people, tasks and places fuel you and which drain you. Use a real week from your calendar rather than an ideal one.", "sents": [[0, "Your energy map shows which people, tasks and places fuel you and which drain you.", 0], [6.03, "Use a real week from your calendar rather than an ideal one.", 0]], "v": "r3", "cues": [0]}, "n_2_7_tape": {"dur": 9.6, "text": "Your game tape is one high point and one setback, read for patterns the way a coach reads film. You're looking for what they show about you, rather than who to blame.", "sents": [[0.01, "Your game tape is one high point and one setback, read for patterns the way a coach reads film.", 0], [6.25, "You're looking for what they show about you, rather than who to blame.", 0]], "v": "r3", "cues": [0.01]}, "n_2_9": {"dur": 29.6, "text": "Here's the distinction to remember. A skill is something you've learned to do well. A strength is something you do well that also tends to energize you. That doesn't mean every skill drains you, or that you should only work in your strengths. Sometimes the moment demands a skill you've had to build. But the more you understand what gives you energy, the more intentionally you can draw on your strengths when you need them. Great leadership needs both. Now sort each statement into strength or skill.", "sents": [[0.03, "Here's the distinction to remember.", 0], [2.15, "A skill is something you've learned to do well.", 0], [5.29, "A strength is something you do well that also tends to energize you.", 0], [9.77, "That doesn't mean every skill drains you, or that you should only work in your strengths.", 1], [14.37, "Sometimes the moment demands a skill you've had to build.", 1], [17.85, "But the more you understand what gives you energy, the more intentionally you can draw on your strengths when you need them.", 1], [24.41, "Great leadership needs both.", 1], [26.65, "Now sort each statement into strength or skill.", 2]], "v": "r3", "cues": [0.03, 9.77, 26.65]}, "n_2_12": {"dur": 33.6, "text": "Melissa just shared one of her own setbacks. Here's the shape of it. Two NFL teams turned down her idea for player development. She was frustrated, and she felt inadequate. She treated the no as feedback, kept refining the idea, and pitched it again. Three years later, the NFL said yes, and Player Brand University launched across the entire league. So here's your practice this week: when you hear a no, ask what it can teach you before you decide your next move. You'll do the same with one of your own setbacks in your Playbook.", "sents": [[0.01, "Melissa just shared one of her own setbacks.", 0], [2.75, "Here's the shape of it.", 0], [4.31, "Two NFL teams turned down her idea for player development.", 1], [8.33, "She was frustrated, and she felt inadequate.", 1], [11.47, "She treated the no as feedback, kept refining the idea, and pitched it again.", 2], [16.69, "Three years later, the NFL said yes, and Player Brand University launched across the entire league.", 3], [23.67, "So here's your practice this week: when you hear a no, ask what it can teach you before you decide your next move.", 4], [30.51, "You'll do the same with one of your own setbacks in your Playbook.", 4]], "v": "r3", "cues": [0.01, 4.31, 11.47, 16.69, 23.67]}, "n_2_13": {"dur": 7.84, "text": "Back to Monday morning. You named a value in your check-in. Use it here. Choose your first move, and you'll hear where it leads.", "sents": [[0.01, "Back to Monday morning.", 0], [1.97, "You named a value in your check-in.", 0], [3.89, "Use it here.", 0], [4.95, "Choose your first move, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0.01, 4.95]}, "n_2_13_o0": {"dur": 11.92, "text": "Replying straight away feels decisive. But you spend the morning defending a plan that's already changed, and your team hears the argument before they hear where you stand. Try the other option to compare.", "sents": [[0.03, "Replying straight away feels decisive.", 0], [2.95, "But you spend the morning defending a plan that's already changed, and your team hears the argument before they hear where you stand.", 0], [10.19, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "n_2_13_o1": {"dur": 17.2, "text": "Pause, and go back to the value you named. Ask what leading from it would look like right now, then decide how to respond. Your value won't make the decision for you. It's a filter for how you lead through it. Practice this pause this week, every time a plan changes.", "sents": [[0.03, "Pause, and go back to the value you named.", 0], [3.37, "Ask what leading from it would look like right now, then decide how to respond.", 0], [8.53, "Your value won't make the decision for you.", 0], [11.03, "It's a filter for how you lead through it.", 0], [13.65, "Practice this pause this week, every time a plan changes.", 0]], "v": "r3", "cues": [0.03]}, "n_2_15": {"dur": 10.4, "text": "Time for the drill. It puts you under a little pressure and asks you to respond. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0, "Time for the drill.", 0], [1.53, "It puts you under a little pressure and asks you to respond.", 0], [5.23, "Press play.", 1], [6.19, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0, 5.23]}, "n_2_16": {"dur": 29.6, "text": "Your core rep this week is your values, about fifteen minutes. Circle every one that fits from the list, narrow it to five, then to the three you'd hold even when it costs you. If you have more time, work through your strengths and your energy audit, using last week's calendar rather than an ideal week. And your game tape: one high point and one setback, and what each one shows. Run your core rep, then ask one person how it landed. Select Open your Lesson 2 pages to begin.", "sents": [[0.01, "Your core rep this week is your values, about fifteen minutes.", 0], [4.11, "Circle every one that fits from the list, narrow it to five, then to the three you'd hold even when it costs you.", 0], [11.23, "If you have more time, work through your strengths and your energy audit, using last week's calendar rather than an ideal week.", 1], [18.17, "And your game tape: one high point and one setback, and what each one shows.", 2], [23.35, "Run your core rep, then ask one person how it landed.", 3], [26.61, "Select Open your Lesson 2 pages to begin.", 3]], "v": "r3", "cues": [0.01, 11.23, 18.17, 23.35]}, "n_2_17": {"dur": 9.76, "text": "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist. His work sits where neuroscience meets peak performance. Press play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Dr. Michael Mannino, the Flow Alchemist.", 0], [5.05, "His work sits where neuroscience meets peak performance.", 0], [8.43, "Press play to hear from him.", 1]], "v": "r3", "cues": [0, 8.43]}, "n_2_18": {"dur": 14.4, "text": "Michael's drill is one to run with your team, and it takes three minutes. You can run it now, or save it for your next team meeting. Select Start the timer to walk through it. When you've run it, or once you've planned when you will, tick the box that fits.", "sents": [[0.03, "Michael's drill is one to run with your team, and it takes three minutes.", 0], [4.41, "You can run it now, or save it for your next team meeting.", 1], [7.61, "Select Start the timer to walk through it.", 1], [10.19, "When you've run it, or once you've planned when you will, tick the box that fits.", 1]], "v": "r3", "cues": [0.03, 4.41]}, "n_2_20_q0": {"dur": 12.64, "text": "A few questions to check the main ideas. You're excellent at building financial models, and people often ask you for them. You do it well, but it rarely gives you energy. In this system, what is that?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.63, "You're excellent at building financial models, and people often ask you for them.", 0], [7.43, "You do it well, but it rarely gives you energy.", 0], [10.69, "In this system, what is that?", 0]], "v": "r3", "cues": [0]}, "n_2_20_w0": {"dur": 11.2, "text": "It's a skill: something you've learned to do well. Skills matter, and the moment often calls for them. A strength is something you do well that also tends to give you energy.", "sents": [[0.07, "It's a skill: something you've learned to do well.", 0], [3.43, "Skills matter, and the moment often calls for them.", 0], [7.11, "A strength is something you do well that also tends to give you energy.", 0]], "v": "r3", "cues": [0.07]}, "n_2_20_q1": {"dur": 2.8, "text": "How many core values should you aim to name?", "sents": [[0.05, "How many core values should you aim to name?", 0]], "v": "r3", "cues": [0.05]}, "n_2_20_w1": {"dur": 5.6, "text": "Three to five. With a long list, you have no way to choose between them when it matters.", "sents": [[0.09, "Three to five.", 0], [1.49, "With a long list, you have no way to choose between them when it matters.", 0]], "v": "r3", "cues": [0.09]}, "n_2_20_q2": {"dur": 4.32, "text": "Last one. When you review your game tape, what are you looking for?", "sents": [[0.01, "Last one.", 0], [1.19, "When you review your game tape, what are you looking for?", 0]], "v": "r3", "cues": [0.01]}, "n_2_20_w2": {"dur": 6.32, "text": "Patterns. Read it the way a coach reads film: what you did, and what it shows about you.", "sents": [[0.11, "Patterns.", 0], [1.27, "Read it the way a coach reads film: what you did, and what it shows about you.", 0]], "v": "r3", "cues": [0.11]}, "n_2_21": {"dur": 31.92, "text": "Before you go, a quick recap. Your values are the filter you already use without knowing it. This week, you name them. A skill is something you've learned to do well. A strength also tends to give you energy, so knowing which is which helps you choose where to lean in. And your setbacks are data. Read one the way a coach reads film, because Lesson 3 builds on it. Select Download my answers for a Word copy of what you wrote today. Chapter 8 of the book has Melissa's own story of the teams that said no.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.47, "Your values are the filter you already use without knowing it.", 1], [6.37, "This week, you name them.", 1], [8.37, "A skill is something you've learned to do well.", 2], [11.27, "A strength also tends to give you energy, so knowing which is which helps you choose where to lean in.", 2], [17.11, "And your setbacks are data.", 3], [19.25, "Read one the way a coach reads film, because Lesson 3 builds on it.", 3], [23.71, "Select Download my answers for a Word copy of what you wrote today.", 4], [27.59, "Chapter 8 of the book has Melissa's own story of the teams that said no.", 4]], "v": "r3", "cues": [0.03, 2.47, 8.37, 17.11, 23.71]}, "n_2_22": {"dur": 13.2, "text": "That's Lesson 2 done. Keep going, your pre-season is under way. This week, run your core rep, your values, and ask one person how it landed. Next time you'll build your blueprint from what you collect.", "sents": [[0.03, "That's Lesson 2 done.", 0], [1.75, "Keep going, your pre-season is under way.", 0], [4.87, "This week, run your core rep, your values, and ask one person how it landed.", 1], [10.07, "Next time you'll build your blueprint from what you collect.", 1]], "v": "r3", "cues": [0.03, 4.87]}, "n_3_0": {"dur": 7.92, "text": "Lesson 3 is where you draft your M.V.P.: your mission, your vision and your purpose. Select Start lesson.", "sents": [[0, "Lesson 3 is where you draft your M.V.P.: your mission, your vision and your purpose.", 0], [6.35, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 6.35]}, "n_3_1": {"dur": 18.56, "text": "Read this moment. Which way would you lean? Before you decide, ask yourself: which choice gets me closer to the leader I'm becoming, not just the opportunity that's hardest to say no to? This lesson gives you a way to answer: a purpose, a vision and a mission you've actually written down.", "sents": [[0, "Read this moment.", 0], [1.71, "Which way would you lean?", 0], [3.27, "Before you decide, ask yourself: which choice gets me closer to the leader I'm becoming, not just the opportunity that's hardest to say no to?", 1], [12.27, "This lesson gives you a way to answer: a purpose, a vision and a mission you've actually written down.", 1]], "v": "r3", "cues": [0, 3.27]}, "n_3_3": {"dur": 6.96, "text": "A quick look back at Lesson 2. What makes something a strength rather than a skill? This one isn't scored.", "sents": [[0.05, "A quick look back at Lesson 2.", 0], [2.23, "What makes something a strength rather than a skill?", 1], [5.33, "This one isn't scored.", 1]], "v": "r3", "cues": [0.05, 2.23]}, "n_3_4": {"dur": 23.28, "text": "This lesson gives you a way to choose between two good options: a purpose you've written down. You'll draft your purpose in one sentence, separate from your job title. You'll picture where you are in three to five years, in enough detail to see it, and write a mission statement from a simple template. Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", "sents": [[0, "This lesson gives you a way to choose between two good options: a purpose you've written down.", 0], [5.71, "You'll draft your purpose in one sentence, separate from your job title.", 1], [9.91, "You'll picture where you are in three to five years, in enough detail to see it, and write a mission statement from a simple template.", 2], [17.53, "Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", 3]], "v": "r3", "cues": [0, 5.71, 9.91, 17.53]}, "n_3_7": {"dur": 9.44, "text": "Here's what each part answers. Draft them in order, starting with purpose, because purpose is the tie-breaker. Select each one to hear how to test it.", "sents": [[0.01, "Here's what each part answers.", 0], [1.95, "Draft them in order, starting with purpose, because purpose is the tie-breaker.", 0], [7.07, "Select each one to hear how to test it.", 1]], "v": "r3", "cues": [0.01, 7.07]}, "n_3_7_purpose": {"dur": 9.04, "text": "Your purpose is the impact you want to have, apart from any job. Test it by asking whether it would still be true if you changed employers tomorrow.", "sents": [[0.01, "Your purpose is the impact you want to have, apart from any job.", 0], [4.59, "Test it by asking whether it would still be true if you changed employers tomorrow.", 0]], "v": "r3", "cues": [0.01]}, "n_3_7_vision": {"dur": 8.72, "text": "Your vision is where you are in three to five years, in real detail. If you can't see it, or name who's in the room with you, keep going.", "sents": [[0.01, "Your vision is where you are in three to five years, in real detail.", 0], [4.91, "If you can't see it, or name who's in the room with you, keep going.", 0]], "v": "r3", "cues": [0.01]}, "n_3_7_mission": {"dur": 9.76, "text": "Your mission is what you do, who it's for and what it achieves. Use the template on screen, then read it out loud and change any word that doesn't sound like you.", "sents": [[0.01, "Your mission is what you do, who it's for and what it achieves.", 0], [4.51, "Use the template on screen, then read it out loud and change any word that doesn't sound like you.", 0]], "v": "r3", "cues": [0.01]}, "n_3_7_values": {"dur": 12.48, "text": "Your values are the three to five foundations you come back to daily, and they shape your actions. You named them last lesson. If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", "sents": [[0.01, "Your values are the three to five foundations you come back to daily, and they shape your actions.", 0], [5.95, "You named them last lesson.", 0], [7.65, "If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", 0]], "v": "r3", "cues": [0.01]}, "n_3_10": {"dur": 9.92, "text": "Try sorting these. For each statement, decide whether it's a purpose, a vision or a mission. A tip: the mission is the one with an action in it.", "sents": [[0.03, "Try sorting these.", 0], [1.45, "For each statement, decide whether it's a purpose, a vision or a mission.", 0], [6.41, "A tip: the mission is the one with an action in it.", 1]], "v": "r3", "cues": [0.03, 6.41]}, "n_3_12": {"dur": 30.72, "text": "A year is too long to plan in detail, and a week is too short to build momentum. Ninety days is long enough to finish something real. Each season runs the same loop. You plan two or three goals tied to your M.V.P., act on them daily and weekly, check in every week, then reset. Your Scorecard holds the whole season. You fill in Part 1 this week, your game plan in Lesson 5, and the assessment and reset in Lesson 6. Open it this week and have a look.", "sents": [[0, "A year is too long to plan in detail, and a week is too short to build momentum.", 0], [5.81, "Ninety days is long enough to finish something real.", 0], [9.57, "Each season runs the same loop.", 1], [11.99, "You plan two or three goals tied to your M.V.P., act on them daily and weekly, check in every week, then reset.", 1], [19.77, "Your Scorecard holds the whole season.", 2], [22.47, "You fill in Part 1 this week, your game plan in Lesson 5, and the assessment and reset in Lesson 6.", 2], [29.01, "Open it this week and have a look.", 2]], "v": "r3", "cues": [0, 9.57, 19.77]}, "n_3_13": {"dur": 6.8, "text": "Back to those two opportunities in the same week. Pick the question you'd ask yourself, and you'll hear where it leads.", "sents": [[0.01, "Back to those two opportunities in the same week.", 0], [3.35, "Pick the question you'd ask yourself, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0.01, 3.35]}, "n_3_13_o0": {"dur": 9.04, "text": "It's a fair question, but it's about managing your career. It won't tell you which opportunity is actually yours. Try the other option to compare.", "sents": [[0.07, "It's a fair question, but it's about managing your career.", 0], [4.09, "It won't tell you which opportunity is actually yours.", 0], [7.31, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.07]}, "n_3_13_o1": {"dur": 9.2, "text": "That's the tie-breaker. If neither breaks a value, pick the one that's closer to your vision. If one does break a value, you already know your answer.", "sents": [[0, "That's the tie-breaker.", 0], [1.59, "If neither breaks a value, pick the one that's closer to your vision.", 0], [5.97, "If one does break a value, you already know your answer.", 0]], "v": "r3", "cues": [0]}, "n_3_15": {"dur": 14.48, "text": "Time for the drill. This one tests how much certainty you need before you move. Press play. Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision. Answer each time, and the video carries on.", "sents": [[0, "Time for the drill.", 0], [1.33, "This one tests how much certainty you need before you move.", 0], [5.13, "Press play.", 1], [6.19, "Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision.", 1], [12.01, "Answer each time, and the video carries on.", 1]], "v": "r3", "cues": [0, 5.13]}, "n_3_16": {"dur": 27.52, "text": "Your core rep this week is your purpose, about twenty minutes. Draft it using your Lesson 2 notes. It only has to be true, so don't wait for perfect. If you have more time, write your vision as if it's already happened, and fill in the mission template. Read it out loud, and change any word that doesn't sound like you. Then move all of it, with your values, into Part 1 of your Scorecard. Both files are on this screen. Run your core rep, then ask one person how it landed.", "sents": [[0.01, "Your core rep this week is your purpose, about twenty minutes.", 0], [3.95, "Draft it using your Lesson 2 notes.", 0], [6.13, "It only has to be true, so don't wait for perfect.", 0], [9.21, "If you have more time, write your vision as if it's already happened, and fill in the mission template.", 1], [14.87, "Read it out loud, and change any word that doesn't sound like you.", 1], [18.55, "Then move all of it, with your values, into Part 1 of your Scorecard.", 2], [22.59, "Both files are on this screen.", 2], [24.51, "Run your core rep, then ask one person how it landed.", 3]], "v": "r3", "cues": [0.01, 9.21, 18.55, 24.51]}, "n_3_17": {"dur": 10.32, "text": "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player. She's a broadcaster who performs live, under pressure, for a living. Press play to hear from her.", "sents": [[0.03, "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player.", 0], [4.81, "She's a broadcaster who performs live, under pressure, for a living.", 0], [8.89, "Press play to hear from her.", 1]], "v": "r3", "cues": [0.03, 8.89]}, "n_3_18": {"dur": 14.88, "text": "LaChina's drill trains agility under pressure, and it takes three minutes. Think of a challenge you're facing right now, select Start the timer, and work through each step. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "LaChina's drill trains agility under pressure, and it takes three minutes.", 0], [4.83, "Think of a challenge you're facing right now, select Start the timer, and work through each step.", 1], [10.55, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 4.83]}, "n_3_20_q0": {"dur": 4.96, "text": "A few questions to check the main ideas. Which of these is a mission statement?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.63, "Which of these is a mission statement?", 0]], "v": "r3", "cues": [0]}, "n_3_20_w0": {"dur": 10.64, "text": "It follows the mission template: an action, who it's for, and what it achieves. The first is a vision, the third is a purpose, and the last is a list of values.", "sents": [[0, "It follows the mission template: an action, who it's for, and what it achieves.", 0], [5.39, "The first is a vision, the third is a purpose, and the last is a list of values.", 0]], "v": "r3", "cues": [0]}, "n_3_20_q1": {"dur": 2.24, "text": "Why do you draft your purpose first?", "sents": [[0.05, "Why do you draft your purpose first?", 0]], "v": "r3", "cues": [0.05]}, "n_3_20_w1": {"dur": 6.08, "text": "Purpose is the tie-breaker. When two good options compete, it tells you which one is yours.", "sents": [[0.05, "Purpose is the tie-breaker.", 0], [2.27, "When two good options compete, it tells you which one is yours.", 0]], "v": "r3", "cues": [0.05]}, "n_3_20_q2": {"dur": 9.04, "text": "Last one. Your purpose is to champion emerging talent, and you're offered a high-profile solo project. What does your purpose suggest?", "sents": [[0.07, "Last one.", 0], [1.27, "Your purpose is to champion emerging talent, and you're offered a high-profile solo project.", 0], [7.35, "What does your purpose suggest?", 0]], "v": "r3", "cues": [0.07]}, "n_3_20_w2": {"dur": 8.08, "text": "Your purpose points to a better yes: a way the work can grow someone else. You'll see this exact story in Lesson 4.", "sents": [[0.01, "Your purpose points to a better yes: a way the work can grow someone else.", 0], [5.27, "You'll see this exact story in Lesson 4.", 0]], "v": "r3", "cues": [0.01]}, "n_3_21": {"dur": 32.8, "text": "Before you go, a quick recap. Your purpose is the tie-breaker. It sits apart from your job title, and when two good options collide, it tells you which one is yours. Your vision is a picture, and your mission is a sentence you can act on tonight. And ninety days is the unit of progress: plan, execute, reflect and reset, with your Scorecard holding the season. Select Download my answers for a Word copy of what you wrote today. If you'd like to go further, Chapter 5 of the book is all about defining your M.V.P.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.43, "Your purpose is the tie-breaker.", 1], [4.87, "It sits apart from your job title, and when two good options collide, it tells you which one is yours.", 1], [10.81, "Your vision is a picture, and your mission is a sentence you can act on tonight.", 2], [15.83, "And ninety days is the unit of progress: plan, execute, reflect and reset, with your Scorecard holding the season.", 3], [23.91, "Select Download my answers for a Word copy of what you wrote today.", 4], [27.19, "If you'd like to go further, Chapter 5 of the book is all about defining your M.V.P.", 4]], "v": "r3", "cues": [0.03, 2.43, 10.81, 15.83, 23.91]}, "n_3_22": {"dur": 15.6, "text": "That's Lesson 3 done. You're halfway through your season, and it shows. This week, run your core rep, your purpose, and ask one person how it landed. Read it out loud every few days. Next time, you'll put your blueprint under pressure.", "sents": [[0, "That's Lesson 3 done.", 0], [1.95, "You're halfway through your season, and it shows.", 0], [4.87, "This week, run your core rep, your purpose, and ask one person how it landed.", 1], [10.37, "Read it out loud every few days.", 1], [12.61, "Next time, you'll put your blueprint under pressure.", 1]], "v": "r3", "cues": [0, 4.87]}, "n_4_0": {"dur": 12.08, "text": "Lesson 4 puts your M.V.P. to work, as a filter for decisions and as your answer when you meet resistance. About forty minutes here, then one core rep this week. Select Start lesson.", "sents": [[0.07, "Lesson 4 puts your M.V.P. to work, as a filter for decisions and as your answer when you meet resistance.", 0], [7.19, "About forty minutes here, then one core rep this week.", 1], [10.45, "Select Start lesson.", 1]], "v": "r3", "cues": [0.07, 7.19]}, "n_4_1": {"dur": 11.36, "text": "Read this moment. What would you say in the next five seconds? That answer is where resilience shows up. This lesson gives you two moves for that moment, and one for the week before it.", "sents": [[0.01, "Read this moment.", 0], [1.71, "What would you say in the next five seconds?", 0], [4.19, "That answer is where resilience shows up.", 1], [6.93, "This lesson gives you two moves for that moment, and one for the week before it.", 1]], "v": "r3", "cues": [0.01, 4.19]}, "n_4_3": {"dur": 6.64, "text": "A quick look back at Lesson 3. What is your purpose statement for, day to day? This one isn't scored.", "sents": [[0, "A quick look back at Lesson 3.", 0], [2.21, "What is your purpose statement for, day to day?", 0], [5.11, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 5.11]}, "n_4_4": {"dur": 26.88, "text": "This lesson is about answering a real request with a better yes or a clear no, using the purpose and mission you wrote last week. You'll run a decision through a four-question filter. You'll name the sentence your inner critic repeats, and answer it from your purpose. You'll turn one outside 'no' into a question that makes your idea stronger. Then you'll find the weak point in each of your ninety-day goals, and plan the pivot while you're calm.", "sents": [[0, "This lesson is about answering a real request with a better yes or a clear no, using the purpose and mission you wrote last week.", 0], [8.57, "You'll run a decision through a four-question filter.", 1], [11.63, "You'll name the sentence your inner critic repeats, and answer it from your purpose.", 2], [16.33, "You'll turn one outside 'no' into a question that makes your idea stronger.", 3], [21.29, "Then you'll find the weak point in each of your ninety-day goals, and plan the pivot while you're calm.", 4]], "v": "r3", "cues": [0, 8.57, 11.63, 16.33, 21.29]}, "n_4_7": {"dur": 31.68, "text": "Here's the filter Melissa just walked through. Ask the questions in order, and stop at the first no. First, does it fit your purpose? If it doesn't, it's a distraction, however good it looks. Second, does it move your mission forward: the action, audience, focus and result you wrote last lesson? Third, does it break one of your values? One broken value outweighs nine good reasons. And last, is there a better yes? Ask who else could grow if you say no, and what you could offer instead.", "sents": [[0.01, "Here's the filter Melissa just walked through.", 0], [2.43, "Ask the questions in order, and stop at the first no.", 0], [6.21, "First, does it fit your purpose?", 1], [8.69, "If it doesn't, it's a distraction, however good it looks.", 1], [12.29, "Second, does it move your mission forward: the action, audience, focus and result you wrote last lesson?", 2], [19.03, "Third, does it break one of your values?", 3], [21.75, "One broken value outweighs nine good reasons.", 3], [25.07, "And last, is there a better yes?", 4], [27.76, "Ask who else could grow if you say no, and what you could offer instead.", 4]], "v": "r3", "cues": [0.01, 6.21, 12.29, 19.03, 25.07]}, "n_4_8": {"dur": 35.44, "text": "Let's look at the shape of Anna's story. Anna's purpose is to champion emerging talent. Her boss offers her a high-profile data project that she'd work on alone, for a full quarter. She runs it through the filter. It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it. The project gets done, David grows, and her boss sees her thinking strategically. She never actually said no. The filter doesn't make you say no. It gives your yes and your no a reason you can explain.", "sents": [[0.01, "Let's look at the shape of Anna's story.", 0], [2.53, "Anna's purpose is to champion emerging talent.", 1], [5.83, "Her boss offers her a high-profile data project that she'd work on alone, for a full quarter.", 1], [11.65, "She runs it through the filter.", 2], [13.45, "It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it.", 2], [22.57, "The project gets done, David grows, and her boss sees her thinking strategically.", 3], [27.65, "She never actually said no.", 3], [29.83, "The filter doesn't make you say no.", 4], [32.03, "It gives your yes and your no a reason you can explain.", 4]], "v": "r3", "cues": [0.01, 2.53, 11.65, 22.57, 29.83]}, "n_4_10": {"dur": 24.4, "text": "Resistance comes from two places, and each one needs a different move. Internal resistance is your inner critic. Name the exact sentence it says and answer it once, in writing, from your purpose. External resistance comes from other people or thin resources. Treat their no as not yet, and ask what the last attempt taught. Sort these into internal and external.", "sents": [[0.03, "Resistance comes from two places, and each one needs a different move.", 0], [5.01, "Internal resistance is your inner critic.", 1], [7.75, "Name the exact sentence it says and answer it once, in writing, from your purpose.", 1], [13.33, "External resistance comes from other people or thin resources.", 1], [17.31, "Treat their no as not yet, and ask what the last attempt taught.", 1], [21.89, "Sort these into internal and external.", 2]], "v": "r3", "cues": [0.03, 5.01, 21.89]}, "n_4_12": {"dur": 6.32, "text": "Back to the room, where everyone is looking at you. Choose what you'd say, and you'll hear where it leads.", "sents": [[0, "Back to the room, where everyone is looking at you.", 0], [3.49, "Choose what you'd say, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0, 3.49]}, "n_4_12_o0": {"dur": 10.64, "text": "That's polite, and it's a missed chance. You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed. Try the other option to compare.", "sents": [[0.03, "That's polite, and it's a missed chance.", 0], [3.37, "You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed.", 0], [8.99, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "n_4_12_o1": {"dur": 8.0, "text": "That's the reframe. You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", "sents": [[0, "That's the reframe.", 0], [1.77, "You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", 0]], "v": "r3", "cues": [0]}, "n_4_14": {"dur": 10.88, "text": "Time for the drill. This one is about how quickly you recover when something goes wrong. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.45, "This one is about how quickly you recover when something goes wrong.", 0], [5.63, "Press play.", 1], [6.57, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0.01, 5.63]}, "n_4_15": {"dur": 34.64, "text": "Your core rep this week is the decision filter, about fifteen minutes. Work the scenario through the four questions, then do the same with one real request from your week. If you have more time, write down the exact sentence your inner critic says, and your answer to it. Then take one real no from the last month and rewrite it as not yet, with the question you'll ask. And find where each of your ninety-day goals is most likely to break, and write the pivot. Run your core rep, then ask one person how it landed. Select Open your Lesson 4 pages to begin.", "sents": [[0.01, "Your core rep this week is the decision filter, about fifteen minutes.", 0], [4.51, "Work the scenario through the four questions, then do the same with one real request from your week.", 0], [10.25, "If you have more time, write down the exact sentence your inner critic says, and your answer to it.", 1], [16.11, "Then take one real no from the last month and rewrite it as not yet, with the question you'll ask.", 1], [22.63, "And find where each of your ninety-day goals is most likely to break, and write the pivot.", 2], [28.35, "Run your core rep, then ask one person how it landed.", 3], [31.81, "Select Open your Lesson 4 pages to begin.", 3]], "v": "r3", "cues": [0.01, 10.25, 22.63, 28.35]}, "n_4_16": {"dur": 10.32, "text": "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator. He helps leaders keep people and technology pulling in the same direction. Press play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator.", 0], [4.81, "He helps leaders keep people and technology pulling in the same direction.", 0], [9.09, "Press play to hear from him.", 1]], "v": "r3", "cues": [0, 9.09]}, "n_4_17": {"dur": 15.44, "text": "Sagar's drill is a fifteen-minute exercise to run with your team, to get everyone aligned on one mission. Save it for your next team meeting, or select Start the timer to see how it runs. When you've run it, or once you've planned when you will, tick the box that fits.", "sents": [[0, "Sagar's drill is a fifteen-minute exercise to run with your team, to get everyone aligned on one mission.", 0], [6.59, "Save it for your next team meeting, or select Start the timer to see how it runs.", 1], [11.29, "When you've run it, or once you've planned when you will, tick the box that fits.", 1]], "v": "r3", "cues": [0, 6.59]}, "n_4_19_q0": {"dur": 6.4, "text": "A few questions to check the main ideas. In the decision filter, when do you stop asking questions?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.73, "In the decision filter, when do you stop asking questions?", 0]], "v": "r3", "cues": [0]}, "n_4_19_w0": {"dur": 7.12, "text": "Stop at the first no. Then look for the better yes: who else could grow, and what you could offer instead.", "sents": [[0.03, "Stop at the first no.", 0], [1.97, "Then look for the better yes: who else could grow, and what you could offer instead.", 0]], "v": "r3", "cues": [0.03]}, "n_4_19_q1": {"dur": 5.12, "text": "Your inner critic says, you're not ready for this. What's the conditioned response?", "sents": [[0.05, "Your inner critic says, you're not ready for this.", 0], [3.53, "What's the conditioned response?", 0]], "v": "r3", "cues": [0.05]}, "n_4_19_w1": {"dur": 7.68, "text": "Name the exact sentence and answer it once, in writing, from your purpose. You don't argue with it, and you don't obey it.", "sents": [[0, "Name the exact sentence and answer it once, in writing, from your purpose.", 0], [5.11, "You don't argue with it, and you don't obey it.", 0]], "v": "r3", "cues": [0]}, "n_4_19_q2": {"dur": 8.24, "text": "Last one. Your ninety-day goal depends on one supplier delivering in week six. What does stress-testing that goal mean?", "sents": [[0.01, "Last one.", 0], [1.25, "Your ninety-day goal depends on one supplier delivering in week six.", 0], [6.07, "What does stress-testing that goal mean?", 0]], "v": "r3", "cues": [0.01]}, "n_4_19_w2": {"dur": 6.24, "text": "Agility is planned ahead. You find the weak link now, and decide the pivot while you're calm.", "sents": [[0.05, "Agility is planned ahead.", 0], [2.33, "You find the weak link now, and decide the pivot while you're calm.", 0]], "v": "r3", "cues": [0.05]}, "n_4_20": {"dur": 35.04, "text": "Before you go, a quick recap. The filter gives your yes and your no a reason. Check purpose, mission and values, then look for the better yes. Resistance comes in two kinds. Name your inner critic and answer it once. Treat an outside no as not yet, and ask a question. And agility is planned before it's needed. Find the weak link in each goal now, and decide the pivot while you're calm. Select Download my answers for a Word copy of what you wrote today. Chapter 7 of the book goes further on agility, including the Foundation Reset.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.39, "The filter gives your yes and your no a reason.", 1], [5.71, "Check purpose, mission and values, then look for the better yes.", 1], [10.21, "Resistance comes in two kinds.", 2], [12.29, "Name your inner critic and answer it once.", 2], [15.13, "Treat an outside no as not yet, and ask a question.", 2], [18.91, "And agility is planned before it's needed.", 3], [21.75, "Find the weak link in each goal now, and decide the pivot while you're calm.", 3], [25.79, "Select Download my answers for a Word copy of what you wrote today.", 4], [30.27, "Chapter 7 of the book goes further on agility, including the Foundation Reset.", 4]], "v": "r3", "cues": [0.03, 2.39, 10.21, 18.91, 25.79]}, "n_4_21": {"dur": 15.52, "text": "That's Lesson 4 done. Four down, and your M.V.P. is starting to do real work. This week, run your core rep: use the filter on one real request, then ask one person how it landed. Next time, you'll build your ninety-day plan.", "sents": [[0.05, "That's Lesson 4 done.", 0], [1.89, "Four down, and your M.V.P. is starting to do real work.", 0], [6.21, "This week, run your core rep: use the filter on one real request, then ask one person how it landed.", 1], [13.03, "Next time, you'll build your ninety-day plan.", 1]], "v": "r3", "cues": [0.05, 6.21]}, "n_5_0": {"dur": 9.44, "text": "Lesson 5 turns your goals into a plan with names and dates on it. About forty minutes here, then one core rep this week. Select Start lesson.", "sents": [[0.03, "Lesson 5 turns your goals into a plan with names and dates on it.", 0], [4.67, "About forty minutes here, then one core rep this week.", 1], [7.97, "Select Start lesson.", 1]], "v": "r3", "cues": [0.03, 4.67]}, "n_5_1": {"dur": 10.32, "text": "Read this moment. Does it sound familiar? A goal you can't start on Monday morning isn't ready yet. This lesson turns wishes into work you can start.", "sents": [[0.05, "Read this moment.", 0], [1.63, "Does it sound familiar?", 0], [3.27, "A goal you can't start on Monday morning isn't ready yet.", 1], [6.97, "This lesson turns wishes into work you can start.", 1]], "v": "r3", "cues": [0.05, 3.27]}, "n_5_3": {"dur": 6.08, "text": "A quick look back at Lesson 4. What does stress-testing a goal mean? This one isn't scored.", "sents": [[0, "A quick look back at Lesson 4.", 0], [2.23, "What does stress-testing a goal mean?", 1], [4.59, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.23]}, "n_5_4": {"dur": 20.48, "text": "This lesson is about writing goals you can start on Monday. You'll list what your vision needs from you, and from the people around you. You'll find the two or three gaps that matter most, and write each one as a SMART goal. Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team and a deadline for every goal.", "sents": [[0, "This lesson is about writing goals you can start on Monday.", 0], [3.71, "You'll list what your vision needs from you, and from the people around you.", 1], [7.79, "You'll find the two or three gaps that matter most, and write each one as a SMART goal.", 2], [12.87, "Then you'll build the plan in Part 3 of your Scorecard, with actions, resources, a support team and a deadline for every goal.", 3]], "v": "r3", "cues": [0, 3.71, 7.79, 12.87]}, "n_5_7": {"dur": 32.08, "text": "Every plan needs two things in place, and most people only check the first. Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing. Lynn had the legal experience. Her gaps were managing people, managing budgets and keeping up with her industry. Relational alignment is how you're set up with others: your manager, your peers, your team and the people at home. Lynn's plan only worked once her spouse, her boss and her team were all pulling the same way.", "sents": [[0.05, "Every plan needs two things in place, and most people only check the first.", 0], [5.49, "Personal readiness is your own state: whether you believe it's achievable, whether you have the energy for it, and which skills are missing.", 1], [12.81, "Lynn had the legal experience.", 1], [14.87, "Her gaps were managing people, managing budgets and keeping up with her industry.", 1], [19.69, "Relational alignment is how you're set up with others: your manager, your peers, your team and the people at home.", 2], [26.51, "Lynn's plan only worked once her spouse, her boss and her team were all pulling the same way.", 2]], "v": "r3", "cues": [0.05, 5.49, 19.69]}, "n_5_9": {"dur": 28.4, "text": "Here's Evan's goal from the video, built one letter at a time. It's specific: partnership proposals from qualified vendors. And it's measurable, because three proposals is something he can count. It's attainable, since sixty days is enough to run a small selection process. And it's relevant, because a technical partner is exactly what his online community needs. And it's time-bound: within sixty days. A goal like this tells you what to do on Monday.", "sents": [[0, "Here's Evan's goal from the video, built one letter at a time.", 0], [4.33, "It's specific: partnership proposals from qualified vendors.", 1], [8.35, "And it's measurable, because three proposals is something he can count.", 1], [12.57, "It's attainable, since sixty days is enough to run a small selection process.", 2], [16.99, "And it's relevant, because a technical partner is exactly what his online community needs.", 2], [22.37, "And it's time-bound: within sixty days.", 3], [25.55, "A goal like this tells you what to do on Monday.", 3]], "v": "r3", "cues": [0, 4.33, 12.57, 22.37]}, "n_5_11": {"dur": 28.96, "text": "Every goal in Part 3 of your Scorecard answers these questions. Actions are the concrete steps you'll take every day or week. Resources are what you need: time, money, an introduction, or one piece of information. Your corner is who's supporting you, at work and at home, and how often you'll check in with them. Set that rhythm now. And every goal gets a deadline and a celebration. The date drives the work, and the celebration makes you want the next one.", "sents": [[0, "Every goal in Part 3 of your Scorecard answers these questions.", 0], [4.45, "Actions are the concrete steps you'll take every day or week.", 1], [8.43, "Resources are what you need: time, money, an introduction, or one piece of information.", 1], [14.43, "Your corner is who's supporting you, at work and at home, and how often you'll check in with them.", 2], [19.99, "Set that rhythm now.", 2], [21.83, "And every goal gets a deadline and a celebration.", 3], [25.09, "The date drives the work, and the celebration makes you want the next one.", 3]], "v": "r3", "cues": [0, 4.45, 14.43, 21.83]}, "n_5_12": {"dur": 7.84, "text": "Back to that budget goal from the start of the lesson. Here's a similar gap. Choose the version you could start on Monday, and you'll hear why.", "sents": [[0, "Back to that budget goal from the start of the lesson.", 0], [2.91, "Here's a similar gap.", 0], [4.43, "Choose the version you could start on Monday, and you'll hear why.", 1]], "v": "r3", "cues": [0, 4.43]}, "n_5_12_o0": {"dur": 7.68, "text": "That's a wish. There's nothing to do on Monday morning, and no way to know when you're done. Try the other option to compare.", "sents": [[0.03, "That's a wish.", 0], [1.57, "There's nothing to do on Monday morning, and no way to know when you're done.", 0], [5.77, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.03]}, "n_5_12_o1": {"dur": 7.44, "text": "That's a SMART goal, and it builds alignment with your manager at the same time. You know exactly what Monday looks like.", "sents": [[0, "That's a SMART goal, and it builds alignment with your manager at the same time.", 0], [4.93, "You know exactly what Monday looks like.", 0]], "v": "r3", "cues": [0]}, "n_5_14": {"dur": 10.48, "text": "Time for the drill. This one puts you in a disagreement, in front of other people. Press play. The video stops a few times so you can answer, and it carries on when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.47, "This one puts you in a disagreement, in front of other people.", 0], [5.35, "Press play.", 1], [6.35, "The video stops a few times so you can answer, and it carries on when you're done.", 1]], "v": "r3", "cues": [0.01, 5.35]}, "n_5_15": {"dur": 31.68, "text": "This is the most useful Playbook week of the season. If you have more time, start by listing everything your vision needs, from you and from the people around you. Your core rep is the middle one, about thirty minutes: rate yourself against that list, pick the two or three gaps that matter most, and write each one as a SMART goal. When you can, build your plan in Part 3 of your Scorecard, and start the weekly check-in in Part 4. Fifteen minutes every week from now on. Run your core rep, then ask one person how it landed.", "sents": [[0, "This is the most useful Playbook week of the season.", 0], [3.59, "If you have more time, start by listing everything your vision needs, from you and from the people around you.", 0], [10.13, "Your core rep is the middle one, about thirty minutes: rate yourself against that list, pick the two or three gaps that matter most, and write each one as a SMART goal.", 1], [20.07, "When you can, build your plan in Part 3 of your Scorecard, and start the weekly check-in in Part 4.", 2], [26.03, "Fifteen minutes every week from now on.", 2], [28.09, "Run your core rep, then ask one person how it landed.", 3]], "v": "r3", "cues": [0, 10.13, 20.07, 28.09]}, "n_5_16": {"dur": 12.24, "text": "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst. She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it. Press play to hear from her.", "sents": [[0, "This lesson's Athleader Pro is Ryall Graber, the Wellness Catalyst.", 0], [4.57, "She's an IFBB Pro, and her story is about what peak performance costs when there's nothing underneath it.", 0], [11.01, "Press play to hear from her.", 1]], "v": "r3", "cues": [0, 11.01]}, "n_5_17": {"dur": 12.08, "text": "Ryall's drill is an energy audit, and it takes three minutes. Select Start the timer and work through each step as it lights up. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0, "Ryall's drill is an energy audit, and it takes three minutes.", 0], [3.83, "Select Start the timer and work through each step as it lights up.", 1], [7.81, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0, 3.83]}, "n_5_19_q0": {"dur": 8.08, "text": "A few questions to check the main ideas. Which part of a SMART goal is missing from: get three mentors to review my plan?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.75, "Which part of a SMART goal is missing from: get three mentors to review my plan?", 0]], "v": "r3", "cues": [0]}, "n_5_19_w0": {"dur": 7.28, "text": "It's time-bound. Three mentors is specific and measurable, but without a date it never becomes urgent.", "sents": [[0, "It's time-bound.", 0], [1.53, "Three mentors is specific and measurable, but without a date it never becomes urgent.", 0]], "v": "r3", "cues": [0]}, "n_5_19_q1": {"dur": 2.08, "text": "What made Lynn's plan hold?", "sents": [[0.05, "What made Lynn's plan hold?", 0]], "v": "r3", "cues": [0.05]}, "n_5_19_w1": {"dur": 6.64, "text": "Her home, her boss and her team were all aligned with the plan. Personal readiness was only half of it.", "sents": [[0.03, "Her home, her boss and her team were all aligned with the plan.", 0], [4.51, "Personal readiness was only half of it.", 0]], "v": "r3", "cues": [0.03]}, "n_5_19_q2": {"dur": 4.88, "text": "Last one. Which question does every goal in your Scorecard answer?", "sents": [[0.15, "Last one.", 0], [1.35, "Which question does every goal in your Scorecard answer?", 0]], "v": "r3", "cues": [0.15]}, "n_5_19_w2": {"dur": 7.04, "text": "Every goal names who's in your corner and how often you'll check in, along with actions, resources and a deadline.", "sents": [[0, "Every goal names who's in your corner and how often you'll check in, along with actions, resources and a deadline.", 0]], "v": "r3", "cues": [0]}, "n_5_20": {"dur": 36.08, "text": "Before you go, a quick recap. Readiness has two halves: your own mindset, energy and skills, and your alignment with your manager, your peers, your team and home. A goal you can't start on Monday isn't ready. Make it specific, measurable, attainable, relevant and time-bound. And every goal answers four questions: actions, resources, your corner, and a deadline with a celebration. That's Part 3 of your Scorecard. Select Download my answers for a Word copy of what you wrote today. Chapter 11 of the book is all about the 90-Day Way.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.35, "Readiness has two halves: your own mindset, energy and skills, and your alignment with your manager, your peers, your team and home.", 1], [11.79, "A goal you can't start on Monday isn't ready.", 2], [14.77, "Make it specific, measurable, attainable, relevant and time-bound.", 2], [19.35, "And every goal answers four questions: actions, resources, your corner, and a deadline with a celebration.", 3], [26.89, "That's Part 3 of your Scorecard.", 3], [28.59, "Select Download my answers for a Word copy of what you wrote today.", 4], [32.81, "Chapter 11 of the book is all about the 90-Day Way.", 4]], "v": "r3", "cues": [0.03, 2.35, 11.79, 19.35, 28.59]}, "n_5_21": {"dur": 13.36, "text": "That's Lesson 5 done. One lesson to go, and you've built a plan you can start on Monday. This week, run your core rep, your SMART goals, and ask one person how it landed. Next time is the victory lap.", "sents": [[0.01, "That's Lesson 5 done.", 0], [2.11, "One lesson to go, and you've built a plan you can start on Monday.", 0], [6.09, "This week, run your core rep, your SMART goals, and ask one person how it landed.", 1], [11.41, "Next time is the victory lap.", 1]], "v": "r3", "cues": [0.01, 6.09]}, "n_6_0": {"dur": 11.12, "text": "Lesson 6 is your victory lap. You made it to the championship round. You'll look back at the season, see what changed, and set up the next ninety days. Select Start lesson.", "sents": [[0, "Lesson 6 is your victory lap.", 0], [2.67, "You made it to the championship round.", 0], [4.91, "You'll look back at the season, see what changed, and set up the next ninety days.", 1], [9.59, "Select Start lesson.", 1]], "v": "r3", "cues": [0, 4.91]}, "n_6_1": {"dur": 8.24, "text": "Read this moment. You're about to look. The point is to see what changed, and to decide what the next ninety days are for.", "sents": [[0, "Read this moment.", 0], [1.63, "You're about to look.", 1], [3.01, "The point is to see what changed, and to decide what the next ninety days are for.", 1]], "v": "r3", "cues": [0, 1.63]}, "n_6_3": {"dur": 7.36, "text": "A quick look back at Lesson 5. How many questions does every goal answer in your Scorecard? This one isn't scored.", "sents": [[0, "A quick look back at Lesson 5.", 0], [2.23, "How many questions does every goal answer in your Scorecard?", 1], [5.73, "This one isn't scored.", 1]], "v": "r3", "cues": [0, 2.23]}, "n_6_4": {"dur": 21.6, "text": "This lesson is about seeing what changed and setting up the next season. You'll name one specific win for each of the Core 4. You'll rate yourself again, next to your Lesson 1 baseline, and choose one habit per pillar to keep and one thing to stop. Then you'll close the season in Part 6 of your Scorecard, and pick the pillar you'll focus on for the next ninety days.", "sents": [[0.03, "This lesson is about seeing what changed and setting up the next season.", 0], [4.61, "You'll name one specific win for each of the Core 4.", 1], [7.97, "You'll rate yourself again, next to your Lesson 1 baseline, and choose one habit per pillar to keep and one thing to stop.", 2], [15.11, "Then you'll close the season in Part 6 of your Scorecard, and pick the pillar you'll focus on for the next ninety days.", 3]], "v": "r3", "cues": [0.03, 4.61, 7.97, 15.11]}, "n_6_7": {"dur": 11.68, "text": "Here's one question for each pillar. Answer each with a specific moment from this season, because a named moment tells you which strategy worked. If you get stuck on one, select Need a prompt.", "sents": [[0.07, "Here's one question for each pillar.", 0], [2.45, "Answer each with a specific moment from this season, because a named moment tells you which strategy worked.", 0], [8.75, "If you get stuck on one, select Need a prompt.", 1]], "v": "r3", "cues": [0.07, 8.75]}, "n_6_9": {"dur": 17.28, "text": "Now put your Lesson 1 baseline next to today. Your Lesson 1 ratings are on your Playbook pages, in drill 1.2. Enter them on the left, or if you can't find them, rate where you think you started. Then rate yourself again on the same four. The movement matters more than the number.", "sents": [[0, "Now put your Lesson 1 baseline next to today.", 0], [3.03, "Your Lesson 1 ratings are on your Playbook pages, in drill 1.2.", 1], [7.43, "Enter them on the left, or if you can't find them, rate where you think you started.", 1], [12.37, "Then rate yourself again on the same four.", 1], [14.99, "The movement matters more than the number.", 1]], "v": "r3", "cues": [0, 3.03]}, "n_6_11": {"dur": 8.08, "text": "One season ends, and the next one begins with the same four steps. Select each step to see what it looks like for your next season.", "sents": [[0, "One season ends, and the next one begins with the same four steps.", 0], [4.89, "Select each step to see what it looks like for your next season.", 1]], "v": "r3", "cues": [0, 4.89]}, "n_6_12": {"dur": 7.36, "text": "The season's over and your motivation is high. Choose the move that makes next season happen, and you'll hear where it leads.", "sents": [[0.07, "The season's over and your motivation is high.", 0], [3.53, "Choose the move that makes next season happen, and you'll hear where it leads.", 1]], "v": "r3", "cues": [0.07, 3.53]}, "n_6_12_o0": {"dur": 10.08, "text": "Momentum without a plan is how the Playbook ends up on a shelf. You'd get about two weeks of energy, then the old habits come back. Try the other option to compare.", "sents": [[0.05, "Momentum without a plan is how the Playbook ends up on a shelf.", 0], [4.19, "You'd get about two weeks of energy, then the old habits come back.", 0], [8.33, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.05]}, "n_6_12_o1": {"dur": 6.8, "text": "That's the system doing the work, instead of your motivation. The loop keeps running because it's in the calendar.", "sents": [[0.05, "That's the system doing the work, instead of your motivation.", 0], [3.99, "The loop keeps running because it's in the calendar.", 0]], "v": "r3", "cues": [0.05]}, "n_6_14": {"dur": 12.32, "text": "Time for the last drill of the season. Everything you've practiced arrives at once. Press play. Melissa will stop three times and ask you something. Take the time you need, and the video carries on when you're done.", "sents": [[0.03, "Time for the last drill of the season.", 0], [2.47, "Everything you've practiced arrives at once.", 0], [5.15, "Press play.", 1], [6.19, "Melissa will stop three times and ask you something.", 1], [9.21, "Take the time you need, and the video carries on when you're done.", 1]], "v": "r3", "cues": [0.03, 5.15]}, "n_6_15": {"dur": 26.88, "text": "Your core rep this week is your post-season review, about twenty minutes. Write one specific win for each pillar, and rate yourself again next to your Lesson 1 baseline. If you have more time, choose one habit per pillar to keep and one thing to stop, and pick your focus pillar for the next ninety days. Then close the season in Part 6 of your Scorecard. The post-assessment comes at the end of this lesson. Run your core rep, then ask one person how it landed.", "sents": [[0.01, "Your core rep this week is your post-season review, about twenty minutes.", 0], [4.45, "Write one specific win for each pillar, and rate yourself again next to your Lesson 1 baseline.", 0], [10.23, "If you have more time, choose one habit per pillar to keep and one thing to stop, and pick your focus pillar for the next ninety days.", 1], [17.77, "Then close the season in Part 6 of your Scorecard.", 2], [20.91, "The post-assessment comes at the end of this lesson.", 2], [23.71, "Run your core rep, then ask one person how it landed.", 3]], "v": "r3", "cues": [0.01, 10.23, 17.77, 23.71]}, "n_6_16": {"dur": 10.8, "text": "Your last Athleader Pro is Stephanie Johnson, the Momentum Maker. She turns adversity into acceleration, for teams and for herself. Press play to hear from her.", "sents": [[0.01, "Your last Athleader Pro is Stephanie Johnson, the Momentum Maker.", 0], [4.75, "She turns adversity into acceleration, for teams and for herself.", 0], [9.47, "Press play to hear from her.", 1]], "v": "r3", "cues": [0.01, 9.47]}, "n_6_17": {"dur": 12.24, "text": "Stephanie's drill helps you realign under pressure, and it takes three minutes. Select Start the timer and work through each step. When you're done, or once you've planned when you'll run it, tick the box that fits.", "sents": [[0.05, "Stephanie's drill helps you realign under pressure, and it takes three minutes.", 0], [4.99, "Select Start the timer and work through each step.", 1], [8.05, "When you're done, or once you've planned when you'll run it, tick the box that fits.", 1]], "v": "r3", "cues": [0.05, 4.99]}, "n_6_19_q0": {"dur": 7.28, "text": "A few questions to check the main ideas. In this system, what turns one good season into a lasting change?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.65, "In this system, what turns one good season into a lasting change?", 0]], "v": "r3", "cues": [0]}, "n_6_19_w0": {"dur": 6.64, "text": "Running the same ninety-day loop again, on a schedule: plan, execute, reflect and reset.", "sents": [[0.05, "Running the same ninety-day loop again, on a schedule: plan, execute, reflect and reset.", 0]], "v": "r3", "cues": [0.05]}, "n_6_19_q1": {"dur": 4.64, "text": "Why name a specific moment for each pillar, rather than a general feeling?", "sents": [[0.05, "Why name a specific moment for each pillar, rather than a general feeling?", 0]], "v": "r3", "cues": [0.05]}, "n_6_19_w1": {"dur": 5.52, "text": "A named moment shows you which strategy worked, so you know what to keep doing next season.", "sents": [[0.07, "A named moment shows you which strategy worked, so you know what to keep doing next season.", 0]], "v": "r3", "cues": [0.07]}, "n_6_19_q2": {"dur": 5.92, "text": "Your Agility rating went from two to four, and Wellbeing stayed at two. What does that tell you?", "sents": [[0.01, "Your Agility rating went from two to four, and Wellbeing stayed at two.", 0], [4.69, "What does that tell you?", 0]], "v": "r3", "cues": [0.01]}, "n_6_19_w2": {"dur": 7.12, "text": "The gap that closed is your win. The gap that didn't is a strong candidate for your next season's focus.", "sents": [[0.05, "The gap that closed is your win.", 0], [2.65, "The gap that didn't is a strong candidate for your next season's focus.", 0]], "v": "r3", "cues": [0.05]}, "n_6_19_q3": {"dur": 10.32, "text": "Last one. The plan changes, a trusted colleague disagrees, and people are watching, all at the same time. What does a conditioned leader do first?", "sents": [[0.01, "Last one.", 0], [1.19, "The plan changes, a trusted colleague disagrees, and people are watching, all at the same time.", 0], [8.11, "What does a conditioned leader do first?", 0]], "v": "r3", "cues": [0.01]}, "n_6_19_w3": {"dur": 7.84, "text": "Notice your own reaction first, then choose the next move on purpose. That's what every drill this season has practiced.", "sents": [[0, "Notice your own reaction first, then choose the next move on purpose.", 0], [5.19, "That's what every drill this season has practiced.", 0]], "v": "r3", "cues": [0]}, "n_6_20": {"dur": 34.08, "text": "Before you finish, a quick recap. Name the win and keep the habit. A specific moment for each pillar is how the change sticks. The gap that closed is your win, and the gap that didn't is next season's focus. Your Lesson 1 baseline next to today's rating says it all. And the loop is the result: plan, execute, reflect and reset, with a check-in in your calendar every Friday. Select Download my answers for a Word copy of what you wrote today. Chapter 6 of the book explains why conditioning outperforms training.", "sents": [[0.03, "Before you finish, a quick recap.", 0], [2.41, "Name the win and keep the habit.", 1], [4.95, "A specific moment for each pillar is how the change sticks.", 1], [8.91, "The gap that closed is your win, and the gap that didn't is next season's focus.", 2], [14.25, "Your Lesson 1 baseline next to today's rating says it all.", 2], [17.99, "And the loop is the result: plan, execute, reflect and reset, with a check-in in your calendar every Friday.", 3], [25.81, "Select Download my answers for a Word copy of what you wrote today.", 4], [29.77, "Chapter 6 of the book explains why conditioning outperforms training.", 4]], "v": "r3", "cues": [0.03, 2.41, 8.91, 17.99, 25.81]}, "n_E2": {"dur": 4.48, "text": "Type the code from the last page of the post-assessment, then select Submit.", "sents": [[0.03, "Type the code from the last page of the post-assessment, then select Submit.", 0]], "v": "r3", "cues": [0.03]}, "n_E4": {"dur": 15.84, "text": "You should be proud of what you've built this season. Share it. Copy the post, open LinkedIn, and add the certificate you just downloaded. Your network gets to see what you've been conditioning, and you might be the reason someone else steps into the Arena. This step is optional.", "sents": [[0.01, "You should be proud of what you've built this season.", 0], [2.87, "Share it.", 0], [3.59, "Copy the post, open LinkedIn, and add the certificate you just downloaded.", 1], [8.17, "Your network gets to see what you've been conditioning, and you might be the reason someone else steps into the Arena.", 1], [14.47, "This step is optional.", 1]], "v": "r3", "cues": [0.01, 3.59]}, "ci_a": {"dur": 21.28, "text": "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention. Take about thirty seconds on each of these. Write what actually went on in you, rather than what you think should have. Only you can see this, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead, and this is where you start to see the gap between instinct and intention.", 0], [7.23, "Take about thirty seconds on each of these.", 1], [9.83, "Write what actually went on in you, rather than what you think should have.", 1], [13.89, "Only you can see this, and it's saved here so you can come back to it.", 1], [17.83, "Select Save on each one as you go, then select Next.", 2]], "v": "r3", "cues": [0.03, 7.23, 17.83]}, "ci_b": {"dur": 9.68, "text": "Now look at what you wrote, and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the honest one.", "sents": [[0.09, "Now look at what you wrote, and pick the pattern that's closest to it.", 0], [3.97, "There's no right answer.", 1], [5.45, "Naming a habit helps you catch it sooner next time, so pick the honest one.", 1]], "v": "r3", "cues": [0.09, 3.97]}, "ci_c": {"dur": 17.2, "text": "Now run the Foundation Reset. Say your five words, the ones you wrote in Lesson 1. Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes. Then take one breath. It takes about a minute and works best standing up, so do it now, before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.23, "Say your five words, the ones you wrote in Lesson 1.", 1], [5.51, "Ask yourself for two next-best steps, and pick the one you'll do in the next ten minutes.", 1], [10.75, "Then take one breath.", 1], [12.61, "It takes about a minute and works best standing up, so do it now, before you move on.", 2]], "v": "r3", "cues": [0, 2.23, 12.61]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "r3", "cues": [0.05]}, "r2_n_G6": {"dur": 28.24, "text": "This is your Benchmark Pre-Assessment, your starting point. It asks how you lead today, and at the end of your season you'll take the same assessment, so you can see what changed. It takes about ten minutes, and your individual answers stay confidential. You need to finish it to open Lesson 1. Select Next when you're ready, and it opens right here. With your results, you'll receive your Growth Guide: your outcomes, and how to get the most from this experience. Keep it somewhere safe for the end of your season.", "sents": [[0, "This is your Benchmark Pre-Assessment, your starting point.", 0], [3.69, "It asks how you lead today, and at the end of your season you'll take the same assessment, so you can see what changed.", 0], [10.21, "It takes about ten minutes, and your individual answers stay confidential.", 1], [14.39, "You need to finish it to open Lesson 1.", 1], [16.75, "Select Next when you're ready, and it opens right here.", 1], [19.97, "With your results, you'll receive your Growth Guide: your outcomes, and how to get the most from this experience.", 2], [26.07, "Keep it somewhere safe for the end of your season.", 2]], "v": "r3", "cues": [0, 10.21, 19.97]}, "r2_form_pre": {"dur": 16.4, "text": "Take your time with these. There are no right answers, and your individual answers stay confidential. You can go back and change answers until you submit. When you submit, a short code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0.01, "Take your time with these.", 0], [1.81, "There are no right answers, and your individual answers stay confidential.", 0], [6.31, "You can go back and change answers until you submit.", 0], [9.61, "When you submit, a short code appears on the last page.", 0], [13.05, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0.01]}, "r2_code_pre": {"dur": 14.56, "text": "Type the code from the last page of the assessment, then select Submit. Lesson 1 opens as soon as the code is accepted. Your Growth Guide comes with your results. Keep it somewhere safe, because at the end of your season you'll compare it with your final results.", "sents": [[0.01, "Type the code from the last page of the assessment, then select Submit.", 0], [4.31, "Lesson 1 opens as soon as the code is accepted.", 0], [7.51, "Your Growth Guide comes with your results.", 1], [9.79, "Keep it somewhere safe, because at the end of your season you'll compare it with your final results.", 1]], "v": "r3", "cues": [0.01, 7.51]}, "r2_pulse": {"dur": 23.44, "text": "Every lesson ends with the same short Pulse Check, your check-in after every lesson, so you can see how you're changing over the season. It asks how often, in the last two weeks, you've practiced each of the Core 4, and whether you did this lesson's reps. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next and it opens right here.", "sents": [[0.01, "Every lesson ends with the same short Pulse Check, your check-in after every lesson, so you can see how you're changing over the season.", 0], [7.83, "It asks how often, in the last two weeks, you've practiced each of the Core 4, and whether you did this lesson's reps.", 1], [14.61, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [21.15, "Select Next and it opens right here.", 2]], "v": "r3", "cues": [0.01, 7.83, 14.61]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_code_pulse": {"dur": 5.84, "text": "Type the code from the last page of the Pulse Check, then select Submit. That completes the lesson.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.37, "That completes the lesson.", 0]], "v": "r3", "cues": [0.01]}, "r2_n_E1": {"dur": 17.6, "text": "You've finished all six lessons. The last step is the post-assessment: the same questions you answered before Lesson 1, so you can see what's changed, then a few about how your manager has led. It takes about eight minutes, and your Growth Guide comes with your results. Select Next and it opens right here.", "sents": [[0.01, "You've finished all six lessons.", 0], [2.55, "The last step is the post-assessment: the same questions you answered before Lesson 1, so you can see what's changed, then a few about how your manager has led.", 0], [11.69, "It takes about eight minutes, and your Growth Guide comes with your results.", 1], [15.37, "Select Next and it opens right here.", 1]], "v": "r3", "cues": [0.01, 11.69]}, "r2_form_post": {"dur": 10.56, "text": "Answer for where you are now, not where you started. When you submit, your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0.03, "Answer for where you are now, not where you started.", 0], [3.69, "When you submit, your code appears on the last page.", 0], [7.17, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0.03]}, "r2_cert": {"dur": 16.16, "text": "Congratulations. You've completed the M.V.P. Accelerator, and this certificate is yours. You earned it. Type your name the way you want it printed, then select Download my certificate. It saves as a PDF you can print, keep, and share on the next screen.", "sents": [[0, "Congratulations.", 0], [1.33, "You've completed the M.V.P. Accelerator, and this certificate is yours.", 0], [6.07, "You earned it.", 0], [7.35, "Type your name the way you want it printed, then select Download my certificate.", 1], [11.91, "It saves as a PDF you can print, keep, and share on the next screen.", 1]], "v": "r3", "cues": [0, 7.35]}, "r2_form_wall": {"dur": 24.56, "text": "Before you go, pay it forward. The Wall of Fame is where each group leaves something for the next one. Share one moment from your season that showed you what had changed. We're in this together, and your words help the next group step into the Arena. If you'd like to stay connected to the Athleadership community, select the button for podcasts, newsletters and events. Both steps are optional, and when you're done, you can close the course.", "sents": [[0.03, "Before you go, pay it forward.", 0], [2.55, "The Wall of Fame is where each group leaves something for the next one.", 0], [6.29, "Share one moment from your season that showed you what had changed.", 1], [10.25, "We're in this together, and your words help the next group step into the Arena.", 1], [14.63, "If you'd like to stay connected to the Athleadership community, select the button for podcasts, newsletters and events.", 2], [21.19, "Both steps are optional, and when you're done, you can close the course.", 2]], "v": "r3", "cues": [0.03, 6.29, 14.63]}};
